-- check.sql — self-check for: Exercise 5 — diagnose a slow query in six steps (50,000 orders)
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 5 checks ──────────';

-- CHECK 1: ix_kh_ngay: keys (khachHangId, ngayDat), INCLUDE maDon and tongTien
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @k NVARCHAR(200) = (SELECT STRING_AGG(c.name, N'','') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.DonHang'') AND i.name = N''ix_kh_ngay'' AND ic.is_included_column = 0);
DECLARE @inc NVARCHAR(200) = (SELECT STRING_AGG(c.name, N'','') WITHIN GROUP (ORDER BY c.name) FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.DonHang'') AND i.name = N''ix_kh_ngay'' AND ic.is_included_column = 1);
SET @ok = IIF(@k = N''khachHangId,ngayDat'' AND @inc LIKE N''%maDon%'' AND @inc LIKE N''%tongTien%'', 1, 0);
SET @info = CONCAT(N''keys = '', COALESCE(@k, N''(no index)''), N'' · include = '', COALESCE(@inc, N''(none)''));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. ix_kh_ngay: keys (khachHangId, ngayDat), INCLUDE maDon and tongTien | ix_kh_ngay: khoá (khachHangId, ngayDat), INCLUDE maDon và tongTien'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. ix_kh_ngay: keys (khachHangId, ngayDat), INCLUDE maDon and tongTien | ix_kh_ngay: khoá (khachHangId, ngayDat), INCLUDE maDon và tongTien', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: Customer 42, year 2025: same rows as the original, newest first
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @t TABLE (n INT IDENTITY(1,1), id INT, maDon VARCHAR(12), ngayDat DATE, tongTien DECIMAL(12,0));
INSERT INTO @t (id, maDon, ngayDat, tongTien) EXEC dbo.prDonHangTrongNam 42, 2025;
DECLARE @ref TABLE (id INT, maDon VARCHAR(12), ngayDat DATE, tongTien DECIMAL(12,0));
INSERT INTO @ref SELECT id, maDon, ngayDat, tongTien FROM dbo.DonHang WHERE khachHangId = 42 AND YEAR(ngayDat) = 2025;
SET @ok = IIF(NOT EXISTS (SELECT id, maDon, ngayDat, tongTien FROM @t EXCEPT SELECT * FROM @ref) AND NOT EXISTS (SELECT * FROM @ref EXCEPT SELECT id, maDon, ngayDat, tongTien FROM @t)
  AND (SELECT COUNT(*) FROM @t) = (SELECT COUNT(*) FROM @ref)
  AND NOT EXISTS (SELECT 1 FROM @t a JOIN @t b ON b.n = a.n + 1 WHERE b.ngayDat > a.ngayDat), 1, 0);
SET @info = CONCAT(N''returned '', (SELECT COUNT(*) FROM @t), N'' rows, expected '', (SELECT COUNT(*) FROM @ref), N'', newest first'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Customer 42, year 2025: same rows as the original, newest first | Khách 42, năm 2025: cùng các dòng như câu gốc, mới nhất trước'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Customer 42, year 2025: same rows as the original, newest first | Khách 42, năm 2025: cùng các dòng như câu gốc, mới nhất trước', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Customer 7, year 2024 and customer 4999, year 2023: same rows
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @t TABLE (n INT IDENTITY(1,1), id INT, maDon VARCHAR(12), ngayDat DATE, tongTien DECIMAL(12,0));
INSERT INTO @t (id, maDon, ngayDat, tongTien) EXEC dbo.prDonHangTrongNam 7, 2024;
DECLARE @ref TABLE (id INT, maDon VARCHAR(12), ngayDat DATE, tongTien DECIMAL(12,0));
INSERT INTO @ref SELECT id, maDon, ngayDat, tongTien FROM dbo.DonHang WHERE khachHangId = 7 AND YEAR(ngayDat) = 2024;
SET @ok = IIF(NOT EXISTS (SELECT id, maDon, ngayDat, tongTien FROM @t EXCEPT SELECT * FROM @ref) AND NOT EXISTS (SELECT * FROM @ref EXCEPT SELECT id, maDon, ngayDat, tongTien FROM @t)
  AND (SELECT COUNT(*) FROM @t) = (SELECT COUNT(*) FROM @ref)
  AND NOT EXISTS (SELECT 1 FROM @t a JOIN @t b ON b.n = a.n + 1 WHERE b.ngayDat > a.ngayDat), 1, 0);
IF @ok = 1 BEGIN DELETE FROM @t; DELETE FROM @ref; INSERT INTO @t (id, maDon, ngayDat, tongTien) EXEC dbo.prDonHangTrongNam 4999, 2023; INSERT INTO @ref SELECT id, maDon, ngayDat, tongTien FROM dbo.DonHang WHERE khachHangId = 4999 AND YEAR(ngayDat) = 2023; SET @ok = IIF(NOT EXISTS (SELECT id, maDon, ngayDat, tongTien FROM @t EXCEPT SELECT * FROM @ref) AND (SELECT COUNT(*) FROM @t) = (SELECT COUNT(*) FROM @ref), 1, 0); END;
SET @info = CONCAT(N''returned '', (SELECT COUNT(*) FROM @t), N'' rows, expected '', (SELECT COUNT(*) FROM @ref), N'', newest first'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Customer 7, year 2024 and customer 4999, year 2023: same rows | Khách 7 năm 2024 và khách 4999 năm 2023: cùng các dòng'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Customer 7, year 2024 and customer 4999, year 2023: same rows | Khách 7 năm 2024 và khách 4999 năm 2023: cùng các dòng', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: The year condition is SARGable (no YEAR/DATEPART/CONVERT in the procedure)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @d NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID(N''dbo.prDonHangTrongNam''));
SET @ok = IIF(@d IS NOT NULL AND @d NOT LIKE N''%YEAR(%'' AND @d NOT LIKE N''%YEAR (%'' AND @d NOT LIKE N''%DATEPART%'' AND @d NOT LIKE N''%CONVERT(%'' AND @d NOT LIKE N''%FORMAT(%'', 1, 0);
SET @info = IIF(@d IS NULL, N''procedure not found'', N''a function still wraps the column'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. The year condition is SARGable (no YEAR/DATEPART/CONVERT in the procedure) | Điều kiện năm SARGable (không YEAR/DATEPART/CONVERT trong procedure)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. The year condition is SARGable (no YEAR/DATEPART/CONVERT in the procedure) | Điều kiện năm SARGable (không YEAR/DATEPART/CONVERT trong procedure)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 5: Measured: one call reads at most 30 pages (sys.dm_exec_procedure_stats)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @x TABLE (id INT, maDon VARCHAR(12), ngayDat DATE, tongTien DECIMAL(12,0));
INSERT INTO @x EXEC dbo.prDonHangTrongNam 42, 2025;   -- first call may include compilation work
INSERT INTO @x EXEC dbo.prDonHangTrongNam 42, 2025;   -- measure this one
DECLARE @r BIGINT = (SELECT TOP (1) last_logical_reads FROM sys.dm_exec_procedure_stats WHERE database_id = DB_ID() AND object_id = OBJECT_ID(N''dbo.prDonHangTrongNam'') ORDER BY last_execution_time DESC);
SET @ok = IIF(@r IS NOT NULL AND @r <= 30, 1, 0);
SET @info = CONCAT(N''last_logical_reads = '', COALESCE(CAST(@r AS NVARCHAR(20)), N''(no stats: procedure missing?)''), N'' (the original query reads 661)'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 5. Measured: one call reads at most 30 pages (sys.dm_exec_procedure_stats) | Đo thật: một lần gọi đọc tối đa 30 trang (sys.dm_exec_procedure_stats)'; END
